1	import { z } from "zod";
2	
3	// Every variable from docs/ARCHITECTURE.md ("Env vars"), one line each, grouped by feature.
4	// All optional, so the API boots anywhere (it skips a database whose URI is missing, with a
5	// warning). Features check their own keys when they first use them, with a clear error.
6	const schema = z.object({
7	  // platform
8	  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
9	  PORT: z.coerce.number().default(3000),
10	  MONGO_URI: z.string().min(1).optional(),
11	  TIGER_URI: z.string().min(1).optional(),
12	  /** Directory of the Expo web export the API serves; unset in development */
13	  WEB_DIST: z.string().optional(),
14	
15	  // labels, briefing (Gemini, paid tier)
16	  GEMINI_API_KEY: z.string().min(1).optional(),
17	  // labels, briefing (ElevenLabs)
18	  ELEVENLABS_API_KEY: z.string().min(1).optional(),
19	  // evidence (Solana mainnet, Memo program)
20	  SOLANA_RPC_URL: z.url().optional(),
21	  SOLANA_KEYPAIR: z.string().min(1).optional(),
22	  // works (Street Manager over SNS)
23	  STREET_MANAGER_TOPIC_ARN: z.string().min(1).optional(),
24	});
25	
26	export type Env = z.infer<typeof schema>;
27	
28	let cached: Env | undefined;
29	
30	/** Parses an environment, treating blank values (`KEY=` in .env) as unset. */
31	export function parseEnv(source: Record<string, string | undefined>): Env {
32	  return schema.parse(Object.fromEntries(Object.entries(source).filter(([, v]) => v !== "")));
33	}
34	
35	/** Parsed on first use, so tests and type-only imports never need a full environment. */
36	export function env(): Env {
37	  cached ??= parseEnv(process.env);
38	  return cached;
39	}
40	
41	/** A variable a feature can't run without. Throws a message that names it, never its value. */
42	export function requireEnv<K extends keyof Env>(key: K): NonNullable<Env[K]> {
43	  const value = env()[key];
44	  if (value === undefined || value === "")
45	    throw new Error(`${String(key)} is not set (see .env.example)`);
46	  return value as NonNullable<Env[K]>;
47	}
